/** A mark as inline HTML: a chip span the CSS gives a light backing in dark mode when needed. */
export const mark = (id: string, cls = ''): string => {
  const b = brands[id];
  if (!b) return '';
  return `<span class="x-brand${cls ? ' ' + cls : ''}"${b.dark ? ' data-dark' : ''}>${b.svg}</span>`;
};
